import {download} from './structure.js';
export class Exporter{
 constructor(canvas,audio){this.canvas=canvas;this.audio=audio;this.active=false;}
 formats(){if(!globalThis.MediaRecorder||!this.canvas.captureStream)return [];return ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4'].filter(t=>MediaRecorder.isTypeSupported(t));}
 async start({height,format,title,onstop}){if(this.active)throw Error('Ya hay una grabación.');await this.audio.init();const mime=this.formats().find(t=>t.startsWith('video/'+format));if(!mime)throw Error('Este navegador no permite grabar '+format+'. Prueba WebM o captura externa.');this.oldSize=[this.canvas.width,this.canvas.height];this.canvas.width=Math.round(height*16/9);this.canvas.height=height;const video=this.canvas.captureStream(30);this.stream=new MediaStream([...video.getVideoTracks(),...this.audio.capture.stream.getAudioTracks()]);this.video=video;this.chunks=[];this.recorder=new MediaRecorder(this.stream,{mimeType:mime,videoBitsPerSecond:height===1080?8000000:4000000});this.recorder.ondataavailable=e=>{if(e.data.size)this.chunks.push(e.data);};this.recorder.onstop=()=>{download(new Blob(this.chunks,{type:mime}),title.replace(/[^\p{L}\p{N} _-]/gu,'').slice(0,70)+'.'+(mime.includes('mp4')?'mp4':'webm'));this.video.getTracks().forEach(t=>t.stop());[this.canvas.width,this.canvas.height]=this.oldSize;this.active=false;onstop?.();};this.recorder.onerror=()=>{this.stop();};this.active=true;this.recorder.start(1000);}
 stop(){if(this.active&&this.recorder.state!=='inactive')this.recorder.stop();}
}
